package com.example.auth.repository;

import com.example.auth.entity.Token;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.time.Instant;
import java.util.Optional;

@Repository
public interface TokenRepository extends JpaRepository<Token, Long> {
    Optional<Token> findByTokenValue(String tokenValue);

    @Modifying
    @Query("DELETE FROM Token t WHERE t.expiresAt < :now OR t.isRevoked = true OR t.isConsumed = true")
    int deleteExpiredOrRevokedOrConsumed(@Param("now") Instant now);

    @Modifying
    @Query("UPDATE Token t SET t.isRevoked = true WHERE t.userId = :userId")
    int revokeAllByUserId(@Param("userId") String userId);

    @Modifying
    @Query("UPDATE Token t SET t.isRevoked = true WHERE t.tokenValue = :tokenValue AND t.isRevoked = false AND t.expiresAt > :now")
    int revokeTokenIfValid(@Param("tokenValue") String tokenValue, @Param("now") Instant now);

    @Modifying
    @Query("UPDATE Token t SET t.isConsumed = true WHERE t.tokenValue = :tokenValue AND t.isConsumed = false AND t.isRevoked = false AND t.expiresAt > :now")
    int consumeTokenIfValid(@Param("tokenValue") String tokenValue, @Param("now") Instant now);
}
