package com.example.auth.service;

import com.example.auth.dto.LoginRequest;
import com.example.auth.dto.TokenValidationRequest;
import com.example.auth.entity.Token;
import com.example.auth.repository.TokenRepository;
import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class AuthService {

    private final TokenRepository tokenRepository;
    private final EntityManager entityManager;
    private final Map<String, Object> locks = new ConcurrentHashMap<>();

    public AuthService(TokenRepository tokenRepository, EntityManager entityManager) {
        this.tokenRepository = tokenRepository;
        this.entityManager = entityManager;
    }

    private String generateToken() {
        return UUID.randomUUID().toString();
    }

    @Transactional
    public Map<String, String> login(LoginRequest request) {
        String userId = request.getUsername();
        Instant now = Instant.now();

        String accessTokenValue = generateToken();
        String refreshTokenValue = generateToken();
        String oneTimeTokenValue = generateToken();

        Token accessToken = new Token(accessTokenValue, userId, "ACCESS", now, now.plusSeconds(600));
        Token refreshToken = new Token(refreshTokenValue, userId, "REFRESH", now, now.plusSeconds(86400));
        Token oneTimeToken = new Token(oneTimeTokenValue, userId, "ONETIME", now, now.plusSeconds(300));

        tokenRepository.save(accessToken);
        tokenRepository.save(refreshToken);
        tokenRepository.save(oneTimeToken);

        return Map.of(
            "accessToken", accessTokenValue,
            "oneTimeToken", oneTimeTokenValue,
            "refreshToken", refreshTokenValue
        );
    }

    @Transactional
    public Map<String, String> renew(String refreshTokenValue) {
        Instant now = Instant.now();

        Token refreshToken = tokenRepository.findByTokenValue(refreshTokenValue)
            .orElseThrow(() -> new RuntimeException("Token not found"));

        if (refreshToken.isRevoked() || refreshToken.isConsumed() || refreshToken.getExpiresAt().isBefore(now) || !"REFRESH".equals(refreshToken.getTokenType())) {
            throw new RuntimeException("Invalid refresh token");
        }

        // Atomically revoke the old refresh token
        int updated = tokenRepository.revokeTokenIfValid(refreshTokenValue, now);
        if (updated == 0) {
            throw new RuntimeException("Refresh token already used");
        }

        String userId = refreshToken.getUserId();
        String newAccessTokenValue = generateToken();
        String newRefreshTokenValue = generateToken();

        Token newAccessToken = new Token(newAccessTokenValue, userId, "ACCESS", now, now.plusSeconds(600));
        Token newRefreshToken = new Token(newRefreshTokenValue, userId, "REFRESH", now, now.plusSeconds(86400));

        tokenRepository.save(newAccessToken);
        tokenRepository.save(newRefreshToken);

        return Map.of(
            "accessToken", newAccessTokenValue,
            "refreshToken", newRefreshTokenValue
        );
    }

    @Transactional
    public Map<String, Object> validateOneTimeToken(TokenValidationRequest request) {
        Instant now = Instant.now();
        String tokenValue = request.getToken();

        Token token = tokenRepository.findByTokenValue(tokenValue)
            .orElseThrow(() -> new RuntimeException("Token not found"));

        if (!"ONETIME".equals(token.getTokenType())) {
            throw new RuntimeException("Not a one-time token");
        }

        if (token.isRevoked() || token.isConsumed() || token.getExpiresAt().isBefore(now)) {
            throw new RuntimeException("Token is invalid, expired, revoked, or already consumed");
        }

        // Atomically consume the token
        int consumed = tokenRepository.consumeTokenIfValid(tokenValue, now);
        if (consumed == 0) {
            throw new RuntimeException("Token already consumed");
        }

        return Map.of(
            "valid", true,
            "message", "Token validated successfully"
        );
    }

    @Transactional
    public void logout(String accessTokenValue) {
        Instant now = Instant.now();

        Token accessToken = tokenRepository.findByTokenValue(accessTokenValue)
            .orElseThrow(() -> new RuntimeException("Token not found"));

        if (accessToken.isRevoked() || accessToken.isConsumed() || accessToken.getExpiresAt().isBefore(now) || !"ACCESS".equals(accessToken.getTokenType())) {
            throw new RuntimeException("Invalid access token");
        }

        String userId = accessToken.getUserId();
        tokenRepository.revokeAllByUserId(userId);
    }

    @Transactional
    public int cleanup() {
        Instant now = Instant.now();
        return tokenRepository.deleteExpiredOrRevokedOrConsumed(now);
    }
}
EOF"}

