package com.example.auth.controller;

import com.example.auth.dto.LoginRequest;
import com.example.auth.dto.TokenValidationRequest;
import com.example.auth.service.AuthService;
import jakarta.servlet.http.Cookie;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Map;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest request, HttpServletResponse response) {
        if (request.getUsername() == null || request.getUsername().isEmpty() ||
            request.getPassword() == null || request.getPassword().isEmpty()) {
            return ResponseEntity.badRequest().body(Map.of("error", "Username and password are required"));
        }

        try {
            Map<String, String> tokens = authService.login(request);

            Cookie refreshTokenCookie = new Cookie("refreshToken", tokens.get("refreshToken"));
            refreshTokenCookie.setHttpOnly(true);
            refreshTokenCookie.setMaxAge(86400);
            refreshTokenCookie.setPath("/");
            response.addCookie(refreshTokenCookie);

            return ResponseEntity.ok(Map.of(
                "accessToken", tokens.get("accessToken"),
                "oneTimeToken", tokens.get("oneTimeToken")
            ));
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(Map.of("error", e.getMessage()));
        }
    }

    @PostMapping("/renew")
    public ResponseEntity<?> renew(@RequestHeader(value = "refreshToken", required = false) String refreshTokenHeader,
                                    @CookieValue(value = "refreshToken", required = false) String refreshTokenCookie,
                                    HttpServletResponse response) {
        String refreshTokenValue = refreshTokenCookie != null ? refreshTokenCookie : refreshTokenHeader;

        if (refreshTokenValue == null || refreshTokenValue.isEmpty()) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("valid", false, "message", "Refresh token is missing"));
        }

        try {
            Map<String, String> tokens = authService.renew(refreshTokenValue);

            Cookie refreshTokenCookieNew = new Cookie("refreshToken", tokens.get("refreshToken"));
            refreshTokenCookieNew.setHttpOnly(true);
            refreshTokenCookieNew.setMaxAge(86400);
            refreshTokenCookieNew.setPath("/");
            response.addCookie(refreshTokenCookieNew);

            return ResponseEntity.ok(Map.of("accessToken", tokens.get("accessToken")));
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("valid", false, "message", e.getMessage()));
        }
    }

    @PostMapping("/logout")
    public ResponseEntity<?> logout(@RequestHeader(value = "Authorization", required = false) String authorization) {
        if (authorization == null || !authorization.startsWith("Bearer ")) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error", "Access token is missing"));
        }

        String accessTokenValue = authorization.substring(7);

        try {
            authService.logout(accessTokenValue);
            return ResponseEntity.ok(Map.of("message", "Logged out successfully"));
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error", e.getMessage()));
        }
    }

    @PostMapping("/validate-token")
    public ResponseEntity<?> validateToken(@RequestBody TokenValidationRequest request) {
        if (request.getToken() == null || request.getToken().isEmpty()) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("valid", false, "message", "Token is missing"));
        }

        try {
            Map<String, Object> result = authService.validateOneTimeToken(request);
            return ResponseEntity.ok(result);
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("valid", false, "message", e.getMessage()));
        }
    }
}
EOF"}

